import { useState, useRef } from "react";
import { Box, Button } from "@mui/material";

const COLORS = ["#1b1b1b", "#FF5733", "#33FF57", "#3357FF", "#F3FF33", "#FF33A8", "#33FFF3"];

const MangeLayout = () => {
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);
  const colorInputRef = useRef(null);

  const handleColorChange = (event) => {
    const color = event.target.value;
    setSelectedColor(color);
    document.documentElement.style.setProperty("--main-bg", color);
  };

  return (
    <Box sx={{ textAlign: "center", mt: 3 }}>
      {/* Button to open the color picker */}
      <Button
        variant="contained"
        onClick={() => colorInputRef.current.click()}
        sx={{ backgroundColor: selectedColor }}
      >
        Open Full Color Palette
      </Button>

      {/* Hidden Color Picker Input */}
      <input

        type="color"
        ref={colorInputRef}
        style={{ display: "none" }}
        onChange={handleColorChange}
      />

      {/* Quick Color Selection with Circles */}
      <Box sx={{ display: "flex", gap: 2, justifyContent: "center", mt: 2 }}>
        {COLORS.map((color, index) => (
          <Box
            key={index}
            onClick={() => handleColorChange({ target: { value: color } })}
            sx={{
              width: 30,
              height: 30,
              borderRadius: "50%",
              backgroundColor: color,
              cursor: "pointer",
              border: "2px solid #fff",
              transition: "transform 0.2s",
              "&:hover": { transform: "scale(1.2)" },
            }}
          />
        ))}
      </Box>
    </Box>
  );
};

export default MangeLayout;
